/**
 * One full card from the model, for the add sheet's Fill with AI and the
 * word screen's Improve with AI.
 */
import { ai as aiApi } from '@/api/endpoints.js';
import type { WordDraft } from '@/db/mutations.js';
import { aiJobFromApi } from '@/sync/mapping.js';
import { noteRefusal } from './quota.js';

/** How often to ask whether the job has finished. */
export const POLL_MS = 1200;

/**
 * Asks the model for the card of one entry and waits for it. Throws when the
 * job fails or comes back without a card, with the server's reason when it
 * gave one.
 */
export async function generateCard(
  notebookId: string,
  headword: string,
  options: { hint?: string; pollMs?: number } = {},
): Promise<WordDraft> {
  const pollMs = options.pollMs ?? POLL_MS;
  let job;
  try {
    job = aiJobFromApi(await aiApi.createCards(notebookId, [headword], options.hint));
  } catch (cause) {
    await noteRefusal(cause);
    throw cause;
  }
  while (job.status === 'queued' || job.status === 'running') {
    await new Promise((resolve) => window.setTimeout(resolve, pollMs));
    job = aiJobFromApi(await aiApi.job(job.id));
  }
  const card = job.cards[0];
  if (job.status !== 'done' || card === undefined) throw new Error(job.error ?? 'failed');
  return card;
}
